(function () {
  "use strict";

  /* ---------- Config ----------
     GitHub Pages cannot process forms itself. Create a free form at
     https://formspree.io (or similar) and paste the endpoint below,
     e.g. "https://formspree.io/f/abcdwxyz".
     While empty, the form falls back to opening the visitor's e-mail app. */
  var FORM_ENDPOINT = "https://formspree.io/f/moeewbva";
  var CONTACT_EMAIL = "info@helvetiapixel.ch";

  /* Each language is a static page (/, /de/, /fr/, /it/) generated by scripts/build.mjs,
     so the content is already translated in the HTML. JS only translates what it injects
     (consent banner, form messages) and remembers an explicit language choice. */
  var FORM_LANG = { en: "English", de: "Deutsch", fr: "Français", it: "Italiano" };
  var dict = window.I18N;
  var current = (document.documentElement.lang || "en").slice(0, 2);
  if (!dict[current]) current = "en";

  function t(key) {
    return (dict[current] && dict[current][key]) || dict.en[key] || "";
  }

  function translate(root) {
    root.querySelectorAll("[data-i18n]").forEach(function (el) {
      var value = t(el.getAttribute("data-i18n"));
      if (value) el.textContent = value;
    });
  }

  // Switcher links: remember the choice (used on the English pages to route returning
  // visitors) and keep the current section when switching.
  document.querySelectorAll(".lang-switch a[data-lang]").forEach(function (link) {
    link.addEventListener("click", function () {
      try { localStorage.setItem("hp-lang", link.getAttribute("data-lang")); } catch (e) {}
      if (location.hash) link.href = link.getAttribute("href") + location.hash;
    });
  });

  var langSelect = document.getElementById("f-lang");
  if (langSelect) langSelect.value = FORM_LANG[current];

  /* ---------- Analytics consent ----------
     Google Analytics (loader in each page's <head>) only runs after "Accept". */
  var banner = document.createElement("div");
  banner.className = "consent";
  banner.setAttribute("role", "region");
  banner.setAttribute("aria-label", "Cookies");
  banner.hidden = true;
  banner.innerHTML =
    '<p><span data-i18n="consent.text"></span> <a href="privacy.html" data-i18n="consent.more"></a></p>' +
    '<div class="consent-actions">' +
    '<button type="button" class="btn btn-outline btn-sm" data-consent="denied" data-i18n="consent.decline"></button>' +
    '<button type="button" class="btn btn-primary btn-sm" data-consent="granted" data-i18n="consent.accept"></button>' +
    "</div>";
  translate(banner);
  document.body.appendChild(banner);

  function getConsent() {
    try { return localStorage.getItem("hp-consent"); } catch (e) { return null; }
  }

  function clearAnalyticsCookies() {
    document.cookie.split(";").forEach(function (c) {
      var name = c.split("=")[0].trim();
      if (name.indexOf("_ga") !== 0) return;
      ["", "; domain=" + location.hostname, "; domain=." + location.hostname.replace(/^www\./, "")].forEach(function (d) {
        document.cookie = name + "=; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/" + d;
      });
    });
  }

  banner.addEventListener("click", function (e) {
    var choice = e.target.getAttribute("data-consent");
    if (!choice) return;
    var previous = getConsent();
    try { localStorage.setItem("hp-consent", choice); } catch (err) {}
    banner.hidden = true;
    if (choice === "granted") {
      window.loadGoogleTag();
    } else if (previous === "granted") {
      // Withdrawn: remove cookies and reload so the already-loaded tag stops
      clearAnalyticsCookies();
      location.reload();
    }
  });

  document.querySelectorAll("[data-consent-open]").forEach(function (link) {
    link.addEventListener("click", function (e) {
      e.preventDefault();
      banner.hidden = false;
    });
  });

  if (!getConsent()) banner.hidden = false;


  /* ---------- Mobile nav ---------- */
  var toggle = document.querySelector(".nav-toggle");
  var nav = document.getElementById("main-nav");
  if (toggle && nav) {
    toggle.addEventListener("click", function () {
      var open = nav.classList.toggle("open");
      toggle.setAttribute("aria-expanded", open ? "true" : "false");
    });
    nav.addEventListener("click", function (e) {
      if (e.target.tagName === "A") {
        nav.classList.remove("open");
        toggle.setAttribute("aria-expanded", "false");
      }
    });
  }

  /* ---------- Footer year ---------- */
  document.getElementById("year").textContent = new Date().getFullYear();

  /* ---------- Contact form ---------- */
  var form = document.getElementById("contact-form");
  if (!form) return;
  var status = document.getElementById("form-status");
  var submitBtn = form.querySelector('button[type="submit"]');
  var submitLabel = submitBtn.querySelector("[data-i18n]");

  // "Plan your migration" etc. pre-select the matching service in the form
  var serviceSelect = document.getElementById("f-service");
  document.querySelectorAll("[data-service]").forEach(function (link) {
    link.addEventListener("click", function () {
      serviceSelect.value = link.getAttribute("data-service");
    });
  });

  function showStatus(key, type) {
    status.textContent = t(key);
    status.className = "form-status field-full " + (type || "");
  }

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    var data = new FormData(form);
    if (data.get("_gotcha")) return; // bot

    var name = String(data.get("name") || "").trim();
    var email = String(data.get("email") || "").trim();
    var message = String(data.get("message") || "").trim();
    if (!name || !message || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      showStatus("form.invalid", "error");
      return;
    }

    data.append("_subject", "Website inquiry: " + data.get("service") + " — " + name);
    data.append("site_language", current);

    if (!FORM_ENDPOINT) {
      var body = [
        "Name: " + name,
        "Email: " + email,
        "Company: " + (data.get("company") || "-"),
        "Service: " + data.get("service"),
        "Language: " + data.get("language"),
        "",
        message
      ].join("\n");
      location.href = "mailto:" + CONTACT_EMAIL +
        "?subject=" + encodeURIComponent(data.get("_subject")) +
        "&body=" + encodeURIComponent(body);
      showStatus("form.mailto", "success");
      return;
    }

    submitBtn.disabled = true;
    submitLabel.textContent = t("form.sending");
    fetch(FORM_ENDPOINT, { method: "POST", body: data, headers: { Accept: "application/json" } })
      .then(function (res) {
        if (!res.ok) throw new Error(res.status);
        form.reset();
        showStatus("form.success", "success");
      })
      .catch(function () { showStatus("form.error", "error"); })
      .then(function () {
        submitBtn.disabled = false;
        submitLabel.textContent = t("form.send");
      });
  });
})();
